class CooperativeHarvestLaw(Contract):
    VERSION = 1

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)
        if prior_state is None:
            self.state["restrict_next_month"] = False

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        targets = {
            "John": 1.0,
            "Kate": 1.0,
            "Jack": 1.0,
            "Emma": 1.0,
            "Luke": 1.0,
        }

        final_catches = {}
        for name in self.agent_names:
            raw = submissions.get(name, 0.0)
            try:
                catch = float(raw)
            except Exception:
                catch = 0.0
            if catch < 0:
                catch = 0.0

            if fish_population <= 20.0:
                catch = min(catch, 1.0)

            if fish_population <= 60.0:
                catch = min(catch, 2.0)

            if self.state.get("restrict_next_month", False):
                catch = min(catch, 1.0)

            final_catches[name] = catch

        total_cap = 5.0
        total_requested = sum(final_catches.values())
        if total_requested > total_cap and total_requested > 0:
            scale = total_cap / total_requested
            for name in final_catches:
                final_catches[name] *= scale

        return final_catches

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        targets = {
            "John": 1.0,
            "Kate": 1.0,
            "Jack": 1.0,
            "Emma": 1.0,
            "Luke": 1.0,
        }

        breach = False
        for name, catch in final_catches.items():
            target = targets.get(name)
            if target is not None and catch > target + 1.0:
                breach = True
                break

        self.state["restrict_next_month"] = breach
